import{_ as i,C as r,o as a,c as s,a0 as t,b as c,w as n,a as l,E as d,a1 as u}from"./chunks/framework.DYS8d9tm.js";const _=JSON.parse('{"title":"Technical Specification: Mutual Fund CAS Ingestion","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/cas_ingestion.md","filePath":"technical/data ingestion/cas_ingestion.md"}'),h={name:"technical/data ingestion/cas_ingestion.md"};function p(g,e,m,f,S,A){const o=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="technical-specification-mutual-fund-cas-ingestion" tabindex="-1">Technical Specification: Mutual Fund CAS Ingestion <a class="header-anchor" href="#technical-specification-mutual-fund-cas-ingestion" aria-label="Permalink to &quot;Technical Specification: Mutual Fund CAS Ingestion&quot;">​</a></h1><p><strong>Document Version:</strong> 1.0.0<br><strong>Status:</strong> Draft / Technical Reference<br><strong>Owner:</strong> Investment Engineering</p><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Consolidated Account Statement (CAS) ingestion pipeline is the most complex data stream in the WealthFam ecosystem. Unlike standard bank statements, CAS files from <strong>CAMS</strong>, <strong>KFintech</strong>, <strong>CDSL</strong> (<code>eCAS@cdslstatement.com</code>, <code>cdslindia</code>, <code>&quot;Central Depository Services&quot;</code>), and <strong>NSDL</strong> contain high-density investment data spanning multiple folios, depository accounts, fund houses (AMCs), and asset classes. This document specifies the forensic extraction and ledger reconciliation logic.</p><h2 id="_2-ingestion-flow" tabindex="-1">2. Ingestion Flow <a class="header-anchor" href="#_2-ingestion-flow" aria-label="Permalink to &quot;2. Ingestion Flow&quot;">​</a></h2>',5)),(a(),c(u,null,{default:n(()=>[d(o,{id:"mermaid-15",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20%22Capture%22%0A%20%20%20%20%20%20%20%20MAIL%5BIMAP%20Sync%20Engine%5D%20--%3E%7CFind%20CAMS%2FKFintech%7C%20PDF%5BEncrypted%20CAS%20PDF%5D%0A%20%20%20%20%20%20%20%20UPLOAD%5BManual%20Upload%5D%20--%3E%20PDF%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Forensic%20Extraction%22%0A%20%20%20%20%20%20%20%20PDF%20--%3E%7CPWD%20Unlock%7C%20PLUMBER%5Bpdfplumber%20%2F%20Extraction%20MS%5D%0A%20%20%20%20%20%20%20%20PLUMBER%20--%3E%7CIdentify%20AMCs%7C%20AMC%5BAMC%20Folio%20Detection%5D%0A%20%20%20%20%20%20%20%20AMC%20--%3E%7CISIN%20Lookup%7C%20MASTER%5BISIN%20Master%20Database%5D%0A%20%20%20%20%20%20%20%20MASTER%20--%3E%7CNormalization%7C%20TXN%5BStandardized%20Transactions%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Ledger%20Reconciliation%22%0A%20%20%20%20%20%20%20%20TXN%20--%3E%7CFolio%20Match%7C%20FOLIO%5BFolio%20Grouping%5D%0A%20%20%20%20%20%20%20%20FOLIO%20--%3E%7CMD5%20Hash%7C%20DEDUP%5BPrecision%20Deduplication%5D%0A%20%20%20%20%20%20%20%20DEDUP%20--%3E%7CSoft-Update%7C%20LEDGER%5B(Investment%20Ledger)%5D%0A%20%20%20%20%20%20%20%20LEDGER%20--%3E%7CXIRR%20Engine%7C%20UI%5BPortfolio%20Dashboard%5D%0A%20%20%20%20end%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="_3-data-extraction-logic" tabindex="-1">3. Data Extraction Logic <a class="header-anchor" href="#_3-data-extraction-logic" aria-label="Permalink to &quot;3. Data Extraction Logic&quot;">​</a></h2><h3 id="_3-1-pdf-decryption-vault-storage-cdsl-hardening" tabindex="-1">3.1 PDF Decryption, Vault Storage &amp; CDSL Hardening <a class="header-anchor" href="#_3-1-pdf-decryption-vault-storage-cdsl-hardening" aria-label="Permalink to &quot;3.1 PDF Decryption, Vault Storage &amp; CDSL Hardening&quot;">​</a></h3><p>CAS files are universally encrypted with a combination of PAN and Date of Birth (DOB) or pure uppercase/lowercase PAN.</p><ul><li><strong>Auto-Trial &amp; Cache</strong>: The system attempts decryption using <code>StatementPasswordCache</code> and user profile metadata (PAN/DOB) before marking the statement <code>PENDING</code> for manual input.</li><li><strong>Persistent Vault Storage &amp; Auto-Unlock</strong>: Unlocked CAS PDFs are stored persistently under <code>VAULT_STORAGE_PATH</code> (<code>/data/vault</code>) with SHA-256 deduplication preventing duplicate version growth across retries. Legacy encrypted statement PDFs on disk are automatically unlocked in-place upon access via <code>VaultService.ensure_unlocked_pdf</code>.</li><li><strong><code>casparser</code> CDSL &amp; Header-Window Patching</strong>: <code>Parser/core/utils.py</code> (<code>patch_casparser()</code>) idempotently patches <strong>both</strong> <code>casparser.process.process_cas_text</code> and the imported <code>casparser.parsers.process_cas_text</code> binding used by <code>read_cas_pdf()</code> to route <code>FileType.CDSL</code> alongside <code>FileType.NSDL</code>, widen CAS type/header detection to <code>text[:5000]</code>, and retry <code>HeaderParseError</code> on cover-page headers past character 1000.</li></ul><h3 id="_3-2-isin-folio-mapping" tabindex="-1">3.2 ISIN &amp; Folio Mapping <a class="header-anchor" href="#_3-2-isin-folio-mapping" aria-label="Permalink to &quot;3.2 ISIN &amp; Folio Mapping&quot;">​</a></h3><p>Mutual funds are identified using ISINs (International Securities Identification Numbers) rather than fund names to prevent &quot;Naming Drift&quot; (where different banks use slightly different names for the same fund).</p><ul><li><strong>Folio Consolidation</strong>: The system aggregates transactions across different AMCs into a single unified view while maintaining the original folio number for audit trails.</li></ul><h2 id="_4-the-ironclad-ledger-standard" tabindex="-1">4. The &quot;Ironclad&quot; Ledger Standard <a class="header-anchor" href="#_4-the-ironclad-ledger-standard" aria-label="Permalink to &quot;4. The &quot;Ironclad&quot; Ledger Standard&quot;">​</a></h2><p>WealthFam enforces a non-destructive, &quot;In-Place Update&quot; policy for mutual fund data.</p><h3 id="_4-1-in-place-updates-vs-destructive-sync" tabindex="-1">4.1 In-Place Updates vs. Destructive Sync <a class="header-anchor" href="#_4-1-in-place-updates-vs-destructive-sync" aria-label="Permalink to &quot;4.1 In-Place Updates vs. Destructive Sync&quot;">​</a></h3><ul><li><strong>Standard Sync</strong>: Traditional apps delete all previous transactions and re-import the CAS. This breaks UUID links to goals, notes, and historical XIRR snapshots.</li><li><strong>WealthFam Sync</strong>: We perform a <strong>Surgical Diff</strong>. Only new transactions are appended, and existing transactions are updated only if their fundamental metadata (Units/NAV) has changed.</li></ul><h3 id="_4-2-precision-calculation" tabindex="-1">4.2 Precision Calculation <a class="header-anchor" href="#_4-2-precision-calculation" aria-label="Permalink to &quot;4.2 Precision Calculation&quot;">​</a></h3><p>Every calculation in the investment ledger uses the <code>Decimal</code> library to 6+ decimal places.</p><ul><li><strong>Zero Drift</strong>: This ensures that &quot;Units × NAV&quot; always matches the &quot;Current Value&quot; exactly, preventing the cent-level rounding errors common in mobile apps.</li></ul><h2 id="_5-xirr-performance-tracking" tabindex="-1">5. XIRR &amp; Performance Tracking <a class="header-anchor" href="#_5-xirr-performance-tracking" aria-label="Permalink to &quot;5. XIRR &amp; Performance Tracking&quot;">​</a></h2><p>XIRR (Extended Internal Rate of Return) is calculated per fund and per folio.</p><ul><li><strong>Cash Flow Verification</strong>: Returns are only calculated on &quot;Confirmed&quot; cash flows (Buy/Sell/Dividend).</li><li><strong>Pending Status</strong>: Transactions from a CAS that do not match existing bank withdrawals are flagged for &quot;Cash Flow Reconciliation&quot; in the UI.</li></ul><h2 id="_6-deduplication-strategy" tabindex="-1">6. Deduplication Strategy <a class="header-anchor" href="#_6-deduplication-strategy" aria-label="Permalink to &quot;6. Deduplication Strategy&quot;">​</a></h2><p>CAS files are cumulative (often containing 6-12 months of history). To prevent duplication:</p><ol><li><strong>MD5 Payload Hashing</strong>: Every transaction is hashed based on <code>(Folio, ISIN, Date, Units, Amount)</code>.</li><li><strong>Idempotency Check</strong>: If the hash already exists in the ledger, the transaction is discarded silently.</li><li><strong>Cross-Source Matching</strong>: The system identifies matches between a CAMS entry and a Bank Statement entry (e.g., a &quot;SIP Debit&quot; in the bank vs. a &quot;Purchase&quot; in the CAMS).</li></ol><h2 id="_7-future-enhancements" tabindex="-1">7. Future Enhancements <a class="header-anchor" href="#_7-future-enhancements" aria-label="Permalink to &quot;7. Future Enhancements&quot;">​</a></h2><ul><li><strong>CAMS API Integration</strong>: Transitioning from PDF parsing to direct CAMS API ingestion for zero-latency sync.</li><li><strong>Tax Harvesting Analysis</strong>: Real-time identification of Short Term (STCG) and Long Term (LTCG) tax implications based on FIFO (First-In-First-Out) logic.</li></ul>',22))])}const D=i(h,[["render",p]]);export{_ as __pageData,D as default};
